            for i in range(m):
                for j in range(0,n,2):
                    if seats[i][j] == '.' and match[i][j] == -1:
                        visited = set()
                        cnt += dfs(i, j, visited)
            return cnt
		#returns the number of elements of the maximum independent set in the bipartite set
        return sum(seats[i][j]=='.' for i in range(m) for j in range(n)) - max_matching()

