class Solution:
    def countNegatives(self, grid: List[List[int]]) -> int:
        result, c = 0, len(grid[0])-1
        for row in grid:
            while c >= 0 and row[c] < 0:
                c -= 1
            result += len(grid[0])-1-c
        return result

import heapq

class Solution:
    def maxEvents(self, events):
        events.sort(reverse=True)
        min_heap = []
        result = 0
        for d in range(1, max(events, key=lambda x:x[1])[1]+1):
            while events and events[-1][0] == d:
                heapq.heappush(min_heap, events.pop()[1])
            while min_heap and min_heap[0] == d-1:
                heapq.heappop(min_heap)
            if not min_heap:
                continue
            heapq.heappop(min_heap)
            result += 1       
        return result

from typing import List
class Solution:
    def isPossible(self, target: List[int]) -> bool:
        if len(target) == 1:
            return target == [1]
        res = sum(target)
        heap = [-elem for elem in target]
        heapify(heap)
        while heap[0]<-1:
            maximum = -heappop(heap)
            res -= maximum

            if res == 1:
                return True
            x = maximum % res
            if x == 0 or (x != 1 and x == maximum):
                return False

            res += x
            heappush(heap,-x)
        return True

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        start = 0
        end = 0
        counter = 0
        store = {'a' : 0, 'b' : 0, 'c' : 0}

        for end in range(len(s)):
            store[s[end]] += 1

            while store['a'] > 0 and store['b'] > 0 and store['c'] > 0:
                counter += (len(s) - end)
                store[s[start]] -= 1
                start += 1

        return counter

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        result, left, count = 0, 0, [0]*3
        for right, c in enumerate(s):
            count[ord(s[right])-ord('a')] += 1
            while all(count):
                count[ord(s[left])-ord('a')] -= 1
                left += 1
            result += left
        return result

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        result, right, count = 0, 0, [0]*3
        for left, c in enumerate(s):
            while right < len(s) and not all(count):
                count[ord(s[right])-ord('a')] += 1
                right += 1
            if all(count):
                result += (len(s)-1) - (right-1) + 1
            count[ord(c)-ord('a')] -= 1
        return result

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        result, left = 0, [-1]*3
        for right, c in enumerate(s):
            left[ord(c)-ord('a')] = right
            result += min(left)+1
        return result
